def transform(grid):
    g = np.array(grid)
    h, w = g.shape
    out = g.copy()
    col = g[:, w - 1]   # right-column ruler (row runs)
    row = g[h - 1, :]   # bottom-row ruler (column runs)
    bg = background(g)
    seen = []
    for c in col:
        if c != bg and c not in seen:
            seen.append(int(c))
    for c in seen:
        ys = [y for y in range(h) if col[y] == c]
        xs = [x for x in range(w) if row[x] == c]
        if not ys or not xs:
            continue
        for y in ys:
            for x in xs:
                out[y, x] = c
        emit(out, f"Colour {c}: fill rows {min(ys)}-{max(ys)} (its run in the right column) "
                  f"x columns {min(xs)}-{max(xs)} (its run in the bottom row).")
    emit(out, "All colour blocks stamped along the diagonal; final grid.")
    return out
